  console.log("POST good:", l1.status, l1.headers["content-type"], l1.body, "set-cookie=" + JSON.stringify(l1.headers["set-cookie"]));
  const cookie = Array.isArray(l1.headers["set-cookie"]) ? l1.headers["set-cookie"][0].split(";")[0] : "";
  // 3 wrong password
  const bad = JSON.stringify({ email: "Sam.Demo@Torpor", password: "nope" });
  let l2 = await req({ host: "127.0.0.1", port: PORT, path: "/api/login", method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(bad) } }, bad);
  console.log("POST wrong-pw:", l2.status, l2.body);
  // 4 bad JSON
  let l3 = await req({ host: "127.0.0.1", port: PORT, path: "/api/login", method: "POST", headers: { "Content-Type": "application/json", "Content-Length": 9 } }, "{notjson}");
  console.log("POST bad-json:", l3.status, l3.body);
  // 4b non-object
  let l3b = await req({ host: "127.0.0.1", port: PORT, path: "/api/login", method: "POST", headers: { "Content-Type": "application/json", "Content-Length": 5 } }, "[1,2]");
  console.log("POST non-object:", l3b.status, l3b.body);
  // 4c oversized
  const big = "x".repeat(4097);
  let l3c = await req({ host: "127.0.0.1", port: PORT, path: "/api/login", method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(big) } }, big);
  console.log("POST oversized:", l3c.status, l3c.body);
  // 4d case/space-insensitive (second session -> expect demo-2)
  const good2 = JSON.stringify({ email: "  SAM.demo@TORPOR  ", password: "demo-password-42" });
  let l4 = await req({ host: "127.0.0.1", port: PORT, path: "/api/login", method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(good2) } }, good2);
  console.log("POST case-space:", l4.status, l4.body, "set-cookie=" + JSON.stringify(l4.headers["set-cookie"]));
  // 5 me with cookie
  let m1 = await req({ host: "127.0.0.1", port: PORT, path: "/api/me", method: "GET", headers: { Cookie: cookie } });
  console.log("GET /api/me cookie:", m1.status, m1.headers["content-type"], m1.body);
  // 6 me without cookie
  let m2 = await req({ host: "127.0.0.1", port: PORT, path: "/api/me", method: "GET" });
  console.log("GET /api/me none:", m2.status, m2.body);
  // 7 me unknown cookie
  let m3 = await req({ host: "127.0.0.1", port: PORT, path: "/api/me", method: "GET", headers: { Cookie: "demo_session=demo-999" } });
  console.log("GET /api/me unknown:", m3.status, m3.body);
  // 8 unknown path + wrong method
  let u1 = await req({ host: "127.0.0.1", port: PORT, path: "/nope", method: "GET" });
  let u2 = await req({ host: "127.0.0.1", port: PORT, path: "/", method: "POST" });
  console.log("GET /nope:", u1.status, "POST /:", u2.status);
  // stop via SIGTERM, measure
  const tKill = Date.now();
  await new Promise((resolve) => { srv.on("exit", resolve); srv.kill("SIGTERM"); });
  console.log("SIGTERM exit ms:", Date.now() - tKill, "exit-code=" + srv.exitCode);
  console.log("STDERR during run:", JSON.stringify(err));
  // invalid port
  const badp = spawn("node", ["demo/app/server.js", "--port", "99999"], { stdio: ["ignore", "pipe", "pipe"] });
  let bo = "", be = "";
  badp.stdout.on("data", (c) => (bo += c));
  badp.stderr.on("data", (c) => (be += c));
  const bcode = await new Promise((r) => badp.on("exit", r));
  console.log("BADPORT exit:", bcode, "stdout=" + JSON.stringify(bo), "stderr=" + JSON.stringify(be));
  // PORT env fallback
  const envp = spawn("node", ["demo/app/server.js"], { env: { ...process.env, PORT: "4568" }, stdio: ["ignore", "pipe", "pipe"] });
  let eo = "";
  envp.stdout.on("data", (c) => (eo += c));
  await new Promise((resolve, reject) => {
    const to = setTimeout(() => reject(new Error("env never ready")), 3000);
    envp.stdout.on("data", () => { clearTimeout(to); resolve(); });
  });
  console.log("ENV-PORT stdout:", JSON.stringify(eo));
  await new Promise((r) => { envp.on("exit", r); envp.kill("SIGINT"); });
  console.log("ALL-DONE");
})().catch((e) => { console.error("HARNESS-FAIL", e); process.exit(1); });
EOF

